// ─── Baked lesson translations (generated, gateway-independent) ──────────────
// Full, reviewed translations of a lesson's title / subtitle / key facts /
// section headings / section bodies for the content languages — so lessons are
// localized instantly with NO runtime AI dependency, even offline or when the
// AI gateway/API key isn't configured in the deployment.
//
// Lessons 01–09 of each era already ship hand-authored translations elsewhere
// (contentTranslations + lessonBody*), so this file covers lessons 10–22, which
// otherwise fall back to the runtime AI translator (dynamicLessonTranslation.ts).
// Macedonian is authored first (the app's primary language); other content
// languages are filled in subsequent batches. Any lesson/lang not present here
// still resolves through the runtime AI layer, so partial coverage is safe.

export interface GenLessonT {
  t?: string;        // title
  s?: string;        // subtitle
  k?: string[];      // keyFacts
  h?: string[];      // section headings
  b?: string[];      // section bodies
}

export type GenContentLang = 'es' | 'ru' | 'mk' | 'de' | 'fr';

